<template>
  <div class="layout-px-spacing">
    <ul class="navbar-nav flex-row mt-2">
      <li>
        <div class="page-header">
          <nav class="breadcrumb-one" aria-label="breadcrumb">
            <ol class="breadcrumb">
              <li class="breadcrumb-item"><a href="javascript:;">Masters</a></li>
              <li class="breadcrumb-item active" aria-current="page">
                <span>Requisitions</span>
              </li>
            </ol>
          </nav>
        </div>
      </li>
    </ul>

    <h3 class="mb-3">REQUISITIONS</h3>

    <div
      class="d-flex flex-column flex-lg-row justify-content-between align-items-lg-center gap-3 mb-3"
    >
      <div class="flex-grow-1 text-center" v-if="!requisition_creation">
        <div class="input-group mx-auto" style="max-width: 600px">
          <input
            type="text"
            class="form-control border-end-0"
            placeholder="Search a word..."
            v-model="filter"
          />
          <button class="input-group-text bg-white border-start-0">
            <svg
              xmlns="http://www.w3.org/2000/svg"
              width="22"
              height="22"
              fill="currentColor"
              class="bi bi-search"
              viewBox="0 0 16 16"
            >
              <path
                d="M11.742 10.344a6.5 6.5 0 1 0-1.397 1.398h-.001l3.85 3.85a1 1 0 0 0 1.415-1.415l-3.85-3.85zm-5.442.656a5 5 0 1 1 0-10 5 5 0 0 1 0 10z"
              />
            </svg>
          </button>
        </div>
      </div>

      <div class="d-flex flex-wrap align-items-center justify-content-center gap-2">
        <div class="btn-group">
          <button
            v-if="
              !requisition_creation &&
              user_permissions.includes('can_create_requisition') &&
              (isAllowedTime() || activity?.status == 1 || activity?.infinity_open)
            "
            type="button"
            class="btn btn-primary"
            @click="
              requisition_creation = true;
              getPendingGrn();
            "
            :disabled="loading_spinner"
          >
            <template v-if="loading_spinner">
              <span class="spinner-border spinner-border-sm"></span>
            </template>
            <template v-else>
              <i class="bi bi-plus-square"></i>
            </template>
          </button>

          <input type="date" class="form-control" v-model="date_filter" />

          <button class="btn btn-secondary text-nowrap" @click="date_filter = 'all'">
            All Data
          </button>
        </div>

        <div
          class="btn-group"
          v-if="!requisition_creation && user_permissions.includes('is_md')"
        >
          <button
            type="button"
            @click="showTrash = !showTrash"
            :class="[
              'btn d-flex align-items-center gap-1',
              showTrash ? 'btn-primary' : 'btn-outline-danger',
            ]"
          >
            <span>{{ showTrash ? "All" : "Trashed" }}</span>

            <svg
              v-if="!showTrash"
              xmlns="http://www.w3.org/2000/svg"
              width="20"
              height="20"
              fill="none"
              stroke="currentColor"
              stroke-width="1.5"
              viewBox="0 0 26 26"
            >
              <polyline points="3 6 5 6 21 6"></polyline>
              <path
                d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"
              ></path>
            </svg>

            <svg
              v-else
              xmlns="http://www.w3.org/2000/svg"
              width="20"
              height="20"
              fill="currentColor"
              class="bi bi-check2-circle"
              viewBox="0 0 16 16"
            >
              <path
                d="M2.5 8a5.5 5.5 0 0 1 8.25-4.764.5.5 0 0 0 .5-.866A6.5 6.5 0 1 0 14.5 8a.5.5 0 0 0-1 0 5.5 5.5 0 1 1-11 0"
              />
              <path
                d="M15.354 3.354a.5.5 0 0 0-.708-.708L8 9.293 5.354 6.646a.5.5 0 1 0-.708.708l3 3a.5.5 0 0 0 .708 0z"
              />
            </svg>
          </button>
        </div>
      </div>
    </div>

    <!-- requisition registration form starts -->
    <form
      v-if="requisition_creation"
      class="p-3 border rounded bg-white shadow"
      @submit.prevent="registerRequisition"
      id="close"
    >
      <h4 class="text-center mb-4">
        {{ incidence?.name?.toUpperCase() ?? " REQUISITIONS" }} REGISTRATION FORM
      </h4>

      <!-- Top Section -->
      <div class="row mb-3">
        <!-- Checkbox Group -->

        <!-- Date Fields -->
        <div class="col-md-8 col-lg-9">
          <div class="row g-2">
            <div class="col-2">
              <label class="form-label small">Proforma?</label>
              <div class="border rounded px-2 py-2 d-flex align-items-center">
                <input
                  type="checkbox"
                  class="form-check-input me-2"
                  @change="fillUseField('proforma')"
                />
                <span class="small">{{
                  use_field.includes("proforma") ? "Yes" : "No"
                }}</span>
              </div>
            </div>

            <div class="col-sm-6 col-md-4 col-lg-3">
              <label class="form-label small">Requisition Date</label>
              <input type="date" class="form-control form-control-sm" v-model="date" />
            </div>

            <div v-if="date" class="col-sm-6 col-md-4 col-lg-3">
              <label class="form-label small">Required Date</label>
              <input
                type="date"
                class="form-control form-control-sm"
                v-model="required_date"
              />
            </div>

            <!-- Approval chains list -->
            <div v-if="required_date" class="col-md-4">
              <label class="form-label small">Select Approval Chain</label>
              <multiselect
                class="w-100"
                v-model="incidence"
                placeholder="Create an incidence"
                label="name"
                :options="incidences"
                :allow-empty="false"
              ></multiselect>
            </div>

            <div v-if="pendingIssueNotes.length" class="col-6 mb-2">
              <div class="card border-danger shadow-sm">
                <div class="card-body py-2">
                  <h6 class="text-danger mb-1">There are pending Issue Notes</h6>

                  <div class="d-flex flex-wrap gap-2">
                    <span
                      v-for="issueNote in pendingIssueNotes"
                      :key="issueNote"
                      class="badge bg-danger"
                    >
                      Issue Note No. 0{{ issueNote }}
                    </span>
                  </div>
                </div>
              </div>
            </div>

            <div v-if="pendingGoodReceivedNotes.length" class="col-12 mb-2">
              <div class="card border-danger shadow-sm">
                <div class="card-body py-2">
                  <h6 class="text-warning mb-1 text-center">There are pending Grns</h6>

                  <div class="d-flex flex-wrap gap-2">
                    <router-link to="/good-received-notes/dashboard">
                      <span
                        v-for="receiveNote in pendingGoodReceivedNotes"
                        :key="receiveNote"
                        class="badge bg-warning me-2 mt-1"
                      >
                        Grn No. 0{{ receiveNote }}
                      </span>
                    </router-link>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      <!-- Middle Section -->
      <div class="row" v-if="incidence">
        <div v-if="![6].includes(incidence.id)" class="col-md-6 col-lg-4 mb-2">
          <label class="form-label small">Select Requisition Type</label>
          <multiselect
            v-model="requisition_type"
            :options="types"
            placeholder="Select Requisition Type"
            :searchable="true"
            multple="false"
            :required="true"
            :allow-empty="false"
          ></multiselect>
        </div>

        <div v-else class="col-md-6 col-lg-4 mb-2">
          <label class="form-label small">Select Group</label>
          <multiselect
            v-model="requisition_type"
            :options="['construction materials', 'spares']"
            placeholder="Select Group"
            :searchable="true"
            multple="false"
            :required="true"
            :allow-empty="false"
          ></multiselect>
        </div>

        <!-- Stores -->
        <div v-if="incidence?.id === 6" class="col-md-6 col-lg-4 mb-2">
          <label class="form-label small">Select Store</label>
          <multiselect
            v-model="store"
            :options="stores"
            placeholder="Select Store"
            label="name"
            :searchable="true"
            multple="false"
            :required="true"
            :allow-empty="false"
          ></multiselect>
        </div>

        <!-- Projects -->
        <!-- v-if="[1,5,6,8].includes(incidence.id)" -->
        <div class="col-md-6 col-lg-3 mb-2">
          <label class="form-label small">Select Cost Center</label>
          <multiselect
            v-model="project"
            :options="projects"
            placeholder="Select A Project"
            :searchable="true"
            label="short_name"
            multple="false"
            :required="true"
            :allow-empty="false"
          ></multiselect>
        </div>

        <!-- Budgets -->
        <div v-if="requisition_type === 'budget'" class="col-md-6 col-lg-5 mb-2">
          <label class="form-label small"
            ><span v-if="loading_budgets" v-html="waitIndicator()"></span
            ><span v-else>Select A Budget</span></label
          >
          <multiselect
            :disabled="loading_budgets"
            v-model="budget"
            :options="budgets"
            placeholder="Select A Budget"
            :searchable="true"
            label="name"
            multple="false"
            :required="true"
            :allow-empty="false"
          ></multiselect>
        </div>

        <!-- Budget items -->
        <div v-if="budget" class="col-md-6 col-lg-6 mb-2">
          <label class="form-label small">Select An Item</label>
          <multiselect
            v-model="budget_item"
            :options="budgetItems"
            placeholder="Select An Item"
            :searchable="true"
            label="name"
            multple="false"
            :required="true"
            :allow-empty="false"
          ></multiselect>
        </div>

        <!-- Budget item description -->
        <div v-if="budget_item" class="col-md-6 col-lg-6 mb-2">
          <label class="form-label small">Select Description</label>
          <multiselect
            v-model="budget_item_description"
            :options="budgetItemDescriptions"
            placeholder="Select An Option"
            :searchable="true"
            label="name"
            multple="false"
            :required="false"
            :allow-empty="false"
          ></multiselect>
        </div>

        <!-- Subcontractor list -->
        <div
          v-if="
            budget_item_description?.name?.toLowerCase().includes('subcontractor') ||
            use_field.includes('subcontractor')
          "
          class="col-md-6 col-lg-5 mb-2"
        >
          <label class="form-label small">Select Subcontractor</label>
          <multiselect
            v-model="selected_subcontractor"
            :options="subcontractors"
            placeholder="Select Subcontractor"
            label="name"
            :searchable="true"
            multple="false"
            :required="true"
            :allow-empty="false"
          ></multiselect>
        </div>

        <!-- Proforma invoice -->
        <div v-if="use_field.includes('proforma')" class="col-md-6 col-lg-4 mb-2">
          <label class="form-label small">Proforma (PDF only)</label>
          <input
            type="file"
            class="form-control form-control-sm"
            @change="handleFileUpload"
            accept="application/pdf"
          />
        </div>

        <div class="col-md-12">
          <textarea
            class="form-control"
            placeholder="Enter Brief Description of the requisition"
            v-model="briefing"
            required
          ></textarea>
        </div>
      </div>

      <!-- Items Section -->
      <div v-if="requisition_type" class="row mb-3 mt-5">
        <div class="col-12 mb-3">
          <h6 class="border-bottom pb-2">Items Section</h6>
        </div>

        <div class="col-md-6 col-lg-6 mb-2">
          <label class="form-label small"
            ><span v-if="loadingBinCards" v-html="waitIndicator()"></span
            ><span v-else>Select Item</span></label
          >

          <multiselect
            v-if="requisition_type === 'labour'"
            v-model="item"
            :options="labours"
            placeholder="Select Labour"
            label="name"
            :searchable="true"
            multple="false"
            :required="true"
            :allow-empty="false"
          ></multiselect>

          <multiselect
            v-else-if="project?.id === 'all'"
            v-model="binCard"
            :options="binCards"
            placeholder="Select Bin Card"
            label="name"
            :searchable="true"
            multple="false"
            :required="true"
            :allow-empty="false"
          >
          </multiselect>

          <multiselect
            v-else-if="incidence?.id === 6"
            v-model="selectedStoreItems"
            :options="storeItems"
            placeholder="Select Store Item"
            track-by="id"
            label="name"
            :searchable="true"
            :multiple="true"
          ></multiselect>

          <multiselect
            v-else-if="
              requisition_type === 'spares' ||
              requisition_type === 'construction materials'
            "
            v-model="item"
            :options="items_list"
            placeholder="Select Option"
            label="name"
            :searchable="true"
            multple="false"
            :required="true"
            :allow-empty="false"
          ></multiselect>

          <input
            v-else
            type="text"
            class="form-control form-control-sm"
            v-model="item"
            placeholder="Enter Item"
          />
        </div>

        <div class="col-md-6 col-lg-6 mb-2">
          <label class="form-label small">Description</label>
          <input
            type="text"
            class="form-control form-control-sm"
            v-model="description"
            placeholder="Enter Description"
          />
        </div>

        <div class="row" v-if="incidence?.id !== 6">
          <div class="col-md-6 col-lg-3 mb-2">
            <label class="form-label small">Unit</label>
            <multiselect
              v-model="units"
              :options="unitList"
              placeholder="Unit"
              label="short_name"
              :searchable="true"
              multple="false"
              :required="true"
              :allow-empty="false"
            ></multiselect>
          </div>

          <div class="col-md-6 col-lg-3 mb-2">
            <label class="form-label small">
              Quantity
              {{
                budget_item_description
                  ? " Budgeted : " +
                    budget_item_description.quantity * budget_item_description.quantity_2
                  : item?.balance_quantity
                  ? " Available : " + item.balance_quantity
                  : ""
              }}
            </label>
            <input
              type="number"
              class="form-control form-control-sm"
              v-model="quantity"
              placeholder="Qty"
              step="any"
              :disabled="
                (['budget'].includes(requisition_type) && !budget_item_description) ||
                (incidence?.id === 6 && !item)
              "
            />
          </div>

          <div class="col-md-6 col-lg-3 mb-2">
            <label class="form-label small">
              <span v-if="requisition_type === 'labour'">Labour Rate</span>
              <span v-else
                >Rate
                {{
                  budget_item_description
                    ? " Budgeted : " + formatNumber(budget_item_description.cost)
                    : ""
                }}</span
              >
            </label>

            <label
              v-if="requisition_type === 'labour'"
              class="form-control form-control-sm"
              >{{ rate.toLocaleString() }}/=</label
            >

            <input
              v-else
              type="number"
              class="form-control form-control-sm"
              v-model="rate"
              placeholder="Enter rate"
              step="any"
              @input="enforceMax()"
              :disabled="
                ['budget'].includes(requisition_type) && !budget_item_description
              "
            />
          </div>

          <div class="col-md-6 col-lg-3 mb-2" v-if="incidence?.id !== 6">
            <label class="form-label small">
              {{
                budget_item_description ? " Balance : " + formatNumber(max_cost) : "Cost"
              }}
            </label>
            <label class="form-control form-control-sm">{{
              formatNumber(quantity * rate)
            }}</label>
          </div>

          <div v-if="incidence?.id !== 6" class="col-md-6 col-lg-5 mb-2">
            <label class="form-label small">Select An Asset</label>
            <multiselect
              v-model="asset"
              :options="assets"
              placeholder="Select An Asset"
              label="name"
              :searchable="true"
              multple="false"
              :required="true"
              :allow-empty="false"
            ></multiselect>
          </div>

          <div v-if="incidence?.id !== 6" class="col-md-6 col-lg-3 mb-2">
            <label class="form-label small"> Receiver </label>
            <multiselect
              v-model="receiver"
              :options="['Vendor', 'Beneficiary']"
              placeholder="Select Receiver"
            >
            </multiselect>
          </div>

          <div v-if="incidence?.id !== 6" class="col-md-6 col-lg-4 mb-2">
            <label class="form-label small">
              {{ receiver }}
            </label>
            <multiselect
              v-if="receiver === 'Vendor'"
              v-model="vendor"
              :options="vendors"
              placeholder="Select Vendor"
              label="name"
              :searchable="true"
              multple="false"
              :required="true"
              :allow-empty="false"
              :disabled="vendor?.id"
            ></multiselect>
            <input
              v-if="receiver === 'Beneficiary'"
              type="text"
              placeholder="Enter Beneficiary Name"
              class="form-control form-control-sm"
              v-model="beneficiary"
            />
          </div>
        </div>

        <!-- Unpaid LPO Card -->
        <div v-if="selectedAssetUnpaidLpos.length > 0" class="col-6 mb-2">
          <div class="card border-danger shadow-sm">
            <div class="card-body py-2">
              <h6 class="text-danger mb-1">Asset has Unpaid Lpos</h6>

              <div class="d-flex flex-wrap gap-2">
                <span
                  v-for="lpo in selectedAssetUnpaidLpos"
                  :key="lpo"
                  class="badge bg-danger"
                >
                  LPO No. 0{{ lpo }}
                </span>
              </div>
            </div>
          </div>
        </div>

        <!-- Open Jobcard Card -->
        <div v-if="selectedAssetOpenJobcards.length > 0" class="col-6 mb-2">
          <div class="card border-warning shadow-sm">
            <div class="card-body py-2">
              <h6 class="text-warning mb-1 text-center">Asset has Open Jobcards</h6>
              <div class="d-flex flex-wrap gap-2">
                <span
                  v-for="jc in selectedAssetOpenJobcards"
                  :key="jc"
                  class="badge bg-warning text-dark"
                >
                  Jobcard No. {{ jc }}
                </span>
              </div>
            </div>
          </div>
        </div>

        <!-- unpaid orders -->

        <div v-if="unpaidOrders.lpos.length > 0" class="col-6 mb-2">
          <div class="card border-danger shadow-sm">
            <div class="card-body py-2">
              <h6 class="text-warning mb-1">You have Unpaid LPOS > 7 days delay</h6>

              <div class="d-flex flex-wrap gap-2">
                <span
                  v-for="lpo in unpaidOrders.lpos"
                  :key="lpo"
                  class="badge bg-warning"
                >
                  LPO No. 0{{ lpo }}
                </span>
              </div>
            </div>
          </div>
        </div>

        <div v-if="unpaidOrders.vouchers.length > 0" class="col-6 mb-2">
          <div class="card border-danger shadow-sm">
            <div class="card-body py-2">
              <h6 class="text-warning mb-1">You have Unpaid Vouchers > 7 days delay</h6>

              <div class="d-flex flex-wrap gap-2">
                <span
                  v-for="lpo in unpaidOrders.vouchers"
                  :key="lpo"
                  class="badge bg-warning"
                >
                  Voucher No. 0{{ lpo }}
                </span>
              </div>
            </div>
          </div>
        </div>

        <table class="table" v-if="selectedStoreItems.length > 0">
          <thead>
            <tr>
              <th>Item</th>
              <th>Unit</th>
              <th>Quantity</th>
              <!-- <th>Rate (Optional)</th> -->
              <th>Description</th>
              <th>Action</th>
            </tr>
          </thead>
          <tbody>
            <tr v-for="(itm, index) in selectedStoreItems" :key="index">
              <td>
                <label class="form-control">{{ itm.name }}</label>
                <small class="text-muted" v-if="itm.balance_quantity">
                  Available: {{ itm.balance_quantity }}
                </small>
              </td>
              <td>
                <multiselect
                  v-model="itm.unit"
                  :options="unitList"
                  placeholder="Select Unit"
                  label="short_name"
                  :searchable="true"
                  :multiple="false"
                  :required="true"
                  :allow-empty="false"
                  @select="(selected) => (itm.unit = selected)"
                ></multiselect>
              </td>
              <td>
                <input
                  type="number"
                  class="form-control"
                  :placeholder="`Enter Quantity, available ${itm.balance_quantity}`"
                  v-model="itm.qty"
                  step="any"
                  :max="itm.balance_quantity"
                  @input="validateQuantity(itm, index)"
                />
              </td>
              <!-- <td>
                <input 
                    type="number" 
                    class="form-control" 
                    placeholder="Enter Rate (optional)" 
                    v-model="itm.rate"
                    step="any"
                    min="0"
                >
            </td> -->
              <td>
                <input
                  type="text"
                  class="form-control"
                  placeholder="Enter description"
                  v-model="itm.descr"
                />
              </td>
              <td>
                <button
                  type="button"
                  class="btn btn-danger btn-sm"
                  @click="removeSelectedStoreItem(index)"
                >
                  <svg
                    xmlns="http://www.w3.org/2000/svg"
                    width="16"
                    height="16"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    stroke-width="2"
                  >
                    <polyline points="3 6 5 6 21 6"></polyline>
                    <path
                      d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"
                    ></path>
                  </svg>
                </button>
              </td>
            </tr>
          </tbody>
        </table>

        <div class="col-md-12 col-lg-12 mb-2 text-end">
          <button
            type="button"
            class="btn btn-outline-success btn-sm mt-4"
            @click="pushItem()"
            :disabled="
              (user_id === 22
                ? asset?.unpaid_lpo_count > 10
                : asset?.has_unpaid_lpo === true) ||
              pendingIssueNotes.length > 0 ||
              asset?.has_open_jobcard === true ||
              pendingGoodReceivedNotes.length > 0
            "
          >
            <svg
              xmlns="http://www.w3.org/2000/svg"
              width="18"
              height="18"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              stroke-width="2"
              stroke-linecap="round"
              stroke-linejoin="round"
              class="feather feather-plus-square"
            >
              <rect x="3" y="3" width="18" height="18" rx="2" ry="2"></rect>
              <line x1="12" y1="8" x2="12" y2="16"></line>
              <line x1="8" y1="12" x2="16" y2="12"></line>
            </svg>
            Add Item
          </button>
        </div>
      </div>

      <!-- Items Table -->
      <div v-if="formRequisitionItems.length > 0" class="row mb-3">
        <div class="col-12">
          <div class="table-responsive custom-table table3">
            <v-client-table
              :data="formRequisitionItems"
              :columns="formItemColumns"
              :options="table_option"
            >
              <template #actions="props">
                <a
                  href="javascript:void(0);"
                  title="Delete"
                  @click="pullItem(props.row.Sno)"
                >
                  <svg
                    xmlns="http://www.w3.org/2000/svg"
                    width="20"
                    height="20"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    stroke-width="1.5"
                    stroke-linecap="round"
                    stroke-linejoin="round"
                    class="text-danger"
                  >
                    <polyline points="3 6 5 6 21 6"></polyline>
                    <path
                      d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"
                    ></path>
                  </svg>
                </a>
              </template>
            </v-client-table>
          </div>
        </div>
      </div>

      <!-- Buttons -->
      <div class="d-flex flex-wrap gap-2 justify-content-end mt-4">
        <button type="button" class="btn btn-outline-danger btn-sm" @click="clearForm()">
          <svg
            style="cursor: pointer"
            xmlns="http://www.w3.org/2000/svg"
            width="26"
            height="26"
            fill="currentColor"
            class="bi bi-trash"
            viewBox="0 0 16 16"
          >
            <path
              d="M5.5 5.5A.5.5 0 0 1 6 6v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m2.5 0a.5.5 0 0 1 .5.5v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m3 .5a.5.5 0 0 0-1 0v6a.5.5 0 0 0 1 0z"
            />
            <path
              d="M14.5 3a1 1 0 0 1-1 1H13v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V4h-.5a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1H6a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1h3.5a1 1 0 0 1 1 1zM4.118 4 4 4.059V13a1 1 0 0 0 1 1h6a1 1 0 0 0 1-1V4.059L11.882 4zM2.5 3h11V2h-11z"
            />
          </svg>
          Clear
        </button>
        <button
          type="button"
          class="btn btn-danger btn-sm"
          @click="(requisition_creation = false), clearForm()"
          id="cancel"
        >
          Cancel
        </button>
        <button
          type="submit"
          class="btn btn-primary btn-sm"
          :disabled="loading_spinner || formRequisitionItems.length <= 0 || loading"
        >
          <span
            v-if="loading"
            class="spinner-border spinner-border-sm me-1"
            role="status"
            aria-hidden="true"
          ></span>
          <span v-else>Register</span>
        </button>
      </div>
    </form>

    <!-- requisition registration form ends-->

    <!-- loading spinner starts -->
    <div v-if="loading_spinner" v-html="tableShimmer()"></div>
    <!-- Loading spinner ends -->

    <!-- requisition table starts -->
    <div v-else v-if="!requisition_creation" class="row layout-top-spacing">
      <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
        <div v-if="isWaiting" v-html="pleaseWait()"></div>
        <div v-else class="panel p-0">
          <div class="custom-table table3">
            <v-client-table
              :data="filteredRequisitions"
              :columns="columns"
              :options="table_option"
            >
              <template #status="props">
                <span class="badge inv-status" :class="'badge-' + props.row.status.class"
                  >{{ props.row.status.key }}
                </span>
              </template>
              <template #sno="{ index }">
                {{ index + 0 }}
              </template>
              <template #actions="props">
                <div class="d-flex justify-content-center align-items-center gap-2">
                  <a
                    href="javascript:void(0);"
                    title="View"
                    data-bs-toggle="modal"
                    data-bs-target="#view_requisition"
                    @click="fillItems(props.row)"
                  >
                    <svg
                      xmlns="http://www.w3.org/2000/svg"
                      width="24"
                      height="24"
                      viewBox="0 0 24 24"
                      fill="none"
                      stroke="currentColor"
                      stroke-width="1.5"
                      stroke-linecap="round"
                      stroke-linejoin="round"
                      class="text-info"
                      data-bs-toggle="modal"
                      data-bs-target="#requisitionItems"
                    >
                      <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"></path>
                      <circle cx="12" cy="12" r="3"></circle>
                    </svg>
                  </a>

                  <a
                    href="javascript:void(0);"
                    title="Edit"
                    @click="openEditModal(props.row)"
                    data-bs-toggle="modal"
                    data-bs-target="#edit-requisition-modal"
                    v-if="user_permissions.includes('can_edit_requisition')"
                  >
                    <svg
                      xmlns="http://www.w3.org/2000/svg"
                      width="24"
                      height="24"
                      viewBox="0 0 24 24"
                      fill="none"
                      stroke="currentColor"
                      stroke-width="1.5"
                      stroke-linecap="round"
                      stroke-linejoin="round"
                      class="text-primary"
                    >
                      <path
                        d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"
                      ></path>
                      <path
                        d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"
                      ></path>
                    </svg>
                  </a>

                  <a
                    v-if="user_permissions.includes('can_print_lpo')"
                    href="javascript:void(0);"
                    @click="printRequisition(props.row)"
                    class="text-success me-2"
                  >
                    <svg
                      xmlns="http://www.w3.org/2000/svg"
                      width="24"
                      height="24"
                      fill="currentColor"
                      class="bi bi-printer"
                      viewBox="0 0 16 16"
                    >
                      <path d="M2.5 8a.5.5 0 1 0 0-1 .5.5 0 0 0 0 1z" />
                      <path
                        d="M5 1a2 2 0 0 0-2 2v2H2a2 2 0 0 0-2 2v3a2 2 0 0 0 2 2h1v1a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2v-1h1a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2h-1V3a2 2 0 0 0-2-2H5zM4 3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1v2H4V3zm1 5a2 2 0 0 0-2 2v1H2a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1h12a1 1 0 0 1 1 1v3a1 1 0 0 1-1 1h-1v-1a2 2 0 0 0-2-2H5zm7 2v3a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1v-3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1z"
                      />
                    </svg>
                  </a>
                  <svg
                    v-if="user_permissions.includes('can_delete_requisition')"
                    @click="DeleteRequisition(props.row)"
                    style="cursor: pointer"
                    xmlns="http://www.w3.org/2000/svg"
                    width="26"
                    height="26"
                    fill="currentColor"
                    class="bi bi-trash text-danger"
                    viewBox="0 0 16 16"
                  >
                    <path
                      d="M5.5 5.5A.5.5 0 0 1 6 6v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m2.5 0a.5.5 0 0 1 .5.5v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m3 .5a.5.5 0 0 0-1 0v6a.5.5 0 0 0 1 0z"
                    />
                    <path
                      d="M14.5 3a1 1 0 0 1-1 1H13v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V4h-.5a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1H6a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1h3.5a1 1 0 0 1 1 1zM4.118 4 4 4.059V13a1 1 0 0 0 1 1h6a1 1 0 0 0 1-1V4.059L11.882 4zM2.5 3h11V2h-11z"
                    />
                  </svg>
                </div>
              </template>
            </v-client-table>
          </div>
        </div>
      </div>
    </div>
    <!-- requisition table ends -->

    <!-- requisition items sterts -->
    <div
      class="modal fade mymodal"
      id="requisitionItems"
      data-bs-backdrop="false"
      data-bs-keyboard="false"
      tabindex="-1"
      aria-labelledby="staticBackdropLabel"
      aria-hidden="true"
    >
      <div class="modal-dialog modal-fullscreen">
        <div class="modal-content">
          <!-- Header -->
          <div class="modal-header">
            <h1 class="modal-title fs-5" id="staticBackdropLabel">Requisition Items</h1>
            <button
              type="button"
              class="btn-close"
              data-bs-dismiss="modal"
              aria-label="Close"
              @click="clearForm()"
              id="close-requisition-modal"
            ></button>
          </div>

          <!-- Body -->
          <div class="modal-body">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
              <div class="panel p-0">
                <div class="custom-table table3 table-responsive">
                  <table class="table table-bordered table-striped">
                    <thead>
                      <tr>
                        <th>Req#</th>
                        <th>Requester</th>
                        <th>Requested</th>
                        <th v-if="requisition.status?.key !== 'Unapproved'">
                          {{ requisition.status?.key }}
                        </th>
                        <th>Source</th>
                        <th>Purpose</th>
                        <th>Project</th>
                        <th>Status</th>
                      </tr>
                    </thead>
                    <tbody>
                      <tr>
                        <td>{{ requisition.id }}</td>
                        <td>{{ requisition.requester }}</td>
                        <td>{{ requisition.date }}</td>
                        <td v-if="requisition.status?.key !== 'Unapproved'">
                          {{ formatDate(requisition.approved_at) }}
                        </td>
                        <td>{{ requisition.type }}</td>
                        <td>{{ requisition.purpose }}</td>
                        <td>{{ requisition.project }}</td>
                        <td>
                          <span
                            class="mb-0 badge"
                            :class="`badge-${requisition.status?.class}`"
                          >
                            {{ requisition.status?.key }}
                          </span>
                        </td>
                      </tr>
                      <tr v-if="requisition.description">
                        <td colspan="7">
                          <b> Brief Description : </b> {{ requisition.description }}
                        </td>
                      </tr>
                      <tr v-if="requisition.remark">
                        <td colspan="7"><b> Remark : </b> {{ requisition.remark }}</td>
                      </tr>
                    </tbody>
                  </table>
                </div>
              </div>
            </div>

            <!-- approval button starts -->
            <div class="mb-2 text-center fw-bold" style="font-size: x-large">
              <strong>Total Cost: </strong>
              <span>
                {{
                  requisition?.items
                    ?.reduce((sum, item) => {
                      const qty = Number(item.quantity) || 0;
                      const rate = Number(item.rate) || 0;
                      return sum + qty * rate;
                    }, 0)
                    .toLocaleString() + "/="
                }}
              </span>
            </div>
            <div class="d-flex">
              <div class="ms-auto">
                <button class="btn btn-primary" @click="addItem = !addItem">
                  <svg
                    xmlns="http://www.w3.org/2000/svg"
                    width="24"
                    height="24"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    stroke-width="2"
                    stroke-linecap="round"
                    stroke-linejoin="round"
                    class="feather feather-plus-square"
                  >
                    <rect x="3" y="3" width="18" height="18" rx="2" ry="2"></rect>
                    <line x1="12" y1="8" x2="12" y2="16"></line>
                    <line x1="8" y1="12" x2="16" y2="12"></line>
                  </svg>
                </button>
              </div>
            </div>
            <div
              v-if="addItem && user_permissions.includes('can_edit_requisition')"
              class="add-item-form my-3"
            >
              <form @submit.prevent="addEditableItems(requisition)">
                <div class="row g-2">
                  <div class="col-12 col-sm-6 col-lg">
                    <input
                      type="text"
                      placeholder="Item"
                      class="form-control"
                      v-model="form.item"
                    />
                  </div>
                  <div class="col-12 col-sm-6 col-lg">
                    <input
                      type="text"
                      placeholder="Description"
                      class="form-control"
                      v-model="form.description"
                    />
                  </div>
                  <div class="col-6 col-sm-4 col-lg">
                    <input
                      type="number"
                      placeholder="Quantity"
                      class="form-control"
                      v-model="form.quantity"
                    />
                  </div>
                  <div class="col-6 col-sm-4 col-lg">
                    <input
                      type="number"
                      placeholder="Rate"
                      class="form-control"
                      v-model="form.rate"
                    />
                  </div>

                  <div class="col-6 col-sm-4 col-lg">
                    <multiselect
                      v-model="form.unit"
                      :options="unitList"
                      placeholder="Select Unit"
                      label="short_name"
                      :searchable="true"
                      multple="false"
                      :required="true"
                      :allow-empty="false"
                    ></multiselect>
                  </div>

                  <div class="col-12 col-sm-6 col-lg">
                    <input
                      type="text"
                      placeholder="Beneficiary"
                      class="form-control"
                      v-model="form.beneficiary"
                    />
                  </div>

                  <div class="col-12 col-sm-4 col-lg-auto">
                    <button
                      type="submit"
                      class="btn btn-primary w-100 w-lg-auto"
                      :disabled="loading"
                    >
                      <span v-if="loading">Saving...</span>
                      <span v-else>Save</span>
                    </button>
                  </div>
                </div>
              </form>
            </div>

            <div
              v-if="
                requisition.status?.key !== 'approved' &&
                user_permissions.includes('can_approve_requisition')
              "
              class="mb-2 text-center"
            >
              <div class="btn-group mb-3">
                <button
                  class="btn btn-primary me-2"
                  @click="status = 3"
                  :disabled="spinner"
                >
                  Approve
                </button>
                <button
                  class="btn btn-danger me-2"
                  @click="status = 4"
                  :disabled="spinner"
                >
                  Reject
                </button>
                <button
                  class="btn btn-warning me-2"
                  @click="(status = 17), (remark = requisition.remark)"
                  :disabled="spinner"
                >
                  Hold Request
                </button>
                <button
                  class="btn btn-info me-2"
                  @click="(status = 14), (remark = requisition.remark)"
                  :disabled="spinner"
                >
                  Remark
                </button>
              </div>

              <div v-if="requisition.requester_id == user_id" class="btn-group mb-3 me-2">
                <button
                  class="btn btn-success"
                  @click="
                    status = 3;
                    fillRequisitionRemark(requisition);
                  "
                  :disabled="spinner"
                >
                  <span v-if="spinner" v-html="loadingSpinner()"></span>
                  <span v-else>Activate</span>
                </button>
              </div>

              <div v-if="status" class="mb-2">
                <span
                  class="badge rounded-pill"
                  :class="{
                    'bg-danger': status == 4,
                    'bg-success': status == 3,
                    'bg-warning': status == 17,
                    'bg-info': status != 3 && status != 4,
                  }"
                  style="font-size: 1rem"
                >
                  {{
                    status == 3
                      ? "Approve Request"
                      : status == 17
                      ? "Hold Request"
                      : status == 4
                      ? "Reject Request"
                      : "Fill Remark"
                  }}
                </span>
              </div>

              <div class="input-group" v-if="status">
                <input
                  type="text"
                  class="form-control"
                  :placeholder="
                    status == 3
                      ? 'Enter Approval Remark'
                      : status == 4
                      ? 'Enter Rejection Remark'
                      : 'Enter Remark'
                  "
                  v-model="remark"
                />
                <button
                  class="btn btn-primary"
                  type="button"
                  :disabled="spinner"
                  @click="fillRequisitionRemark(requisition)"
                >
                  <span v-if="spinner" v-html="loadingSpinner()"></span>
                  <span v-else>Save</span>
                </button>
              </div>
            </div>

            <!-- approval button ends -->

            <form @submit.prevent="registerIncidence()">
              <div class="row layout-top-spacing">
                <!-- Status & Incidence -->
                <div
                  class="col-12 d-flex align-items-center justify-content-between"
                ></div>
                <div
                  v-if="incidence?.id === 6 && store"
                  class="mt-2 col-xl-12 col-lg-12 col-sm-12 layout-spacing"
                >
                  <div class="panel p-0">
                    <div class="custom-table table3">
                      <table class="table table-bordered table-striped">
                        <thead>
                          <tr>
                            <th>Item Requested</th>
                            <th>Item Issued</th>
                            <th>Quantity Issuing</th>
                            <th>Item Condition</th>
                          </tr>
                        </thead>
                        <tbody>
                          <tr v-for="item in requisitionItems" :key="item.id">
                            <td>{{ item.item }}</td>
                            <td>
                              <multiselect
                                v-model="item.store_item"
                                :options="storeItems"
                                placeholder="Select Item"
                                :searchable="true"
                                multple="false"
                                label="name"
                                :required="true"
                                :allow-empty="false"
                              ></multiselect>
                            </td>
                            <td>
                              <input
                                type="number"
                                class="form-control"
                                :placeholder="
                                  'available ' + item.store_item.balance_quantity
                                "
                                v-model="item.issued_quantity"
                                required
                                :max="item.store_item.balance_quantity"
                              />
                            </td>

                            <td>
                              <label type="number" class="form-control">{{
                                item.store_item.condition ?? "Select Item First"
                              }}</label>
                            </td>
                          </tr>
                        </tbody>
                      </table>
                    </div>
                  </div>
                </div>
                <!-- Requisition Items -->
                <div
                  :class="[
                    'col-lg-12',
                    'col-sm-12',
                    'layout-spacing',
                    proforma ? 'col-xl-6' : 'col-xl-12',
                  ]"
                >
                  <div class="panel p-0">
                    <div class="custom-table table3">
                      <v-client-table
                        :data="requisitionItems"
                        :columns="itemColumns"
                        :options="table_option"
                      >
                        <template #description="props">
                          <router-link
                            v-if="requisition.subcontractor"
                            class="btn btn-outline-primary"
                            :to="`/subcontractor/${requisition.subcontractor.id}`"
                            >{{ props.row.description }}</router-link
                          >
                          <router-link
                            v-else-if="
                              props.row.asset_id && requisition.type !== 'jobcard'
                            "
                            class="btn btn-outline-primary"
                            :to="`/assets/fuel-statement/${props.row.asset_id}`"
                            >{{ props.row.description }}</router-link
                          >
                          <router-link
                            v-else-if="requisition.type === 'jobcard'"
                            class="btn btn-outline-primary"
                            :to="`/jobcard/${requisition.item_id}/${props.row.asset_id}`"
                            >{{ props.row.description }}</router-link
                          >
                          <span v-else>{{ props.row.description }}</span>
                        </template>
                        <template #actions="props">
                          <div
                            class="d-flex justify-content-center align-items-center gap-2"
                          >
                            <a
                              href="javascript:void(0);"
                              title="Edit"
                              @click="openEditItemModal(props.row)"
                              v-if="user_permissions.includes('can_edit_requisition')"
                            >
                              <svg
                                xmlns="http://www.w3.org/2000/svg"
                                width="20"
                                height="20"
                                viewBox="0 0 24 24"
                                fill="none"
                                stroke="currentColor"
                                stroke-width="1.5"
                                stroke-linecap="round"
                                stroke-linejoin="round"
                                class="text-primary"
                                data-bs-toggle="modal"
                                data-bs-target="#edit-requisition-items-modal"
                              >
                                <path
                                  d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"
                                ></path>
                                <path
                                  d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"
                                ></path>
                              </svg>
                            </a>

                            <router-link
                              :to="`/assets/fuel-statement/${props.row.asset_id}`"
                              @click="closeModal"
                              v-if="props.row.asset_id"
                            >
                              <button class="btn btn-outline-primary">Diesel</button>
                            </router-link>

                            <!-- <router-link v-if="requisition.subcontractor" class="btn btn-primary " :to="`/subcontractor/${requisition.subcontractor.id}`">Subcontractor</router-link> -->

                            <router-link
                              :to="`/requisition-budget/${props.row.item_id}`"
                              @click="closeModal"
                              v-if="requisition.type === 'budget'"
                            >
                              <button class="btn btn-outline-primary">Budget</button>
                            </router-link>
                          </div>
                        </template>
                      </v-client-table>
                    </div>
                  </div>

                  <!-- Rejection Details -->
                  <div v-if="remarks.length > 0" class="mt-3">
                    <h4 class="text-center text-danger">Rejection Details</h4>
                    <table class="table table-bordered table-striped align-middle">
                      <thead>
                        <tr>
                          <th>Sno</th>
                          <th>Rejected By</th>
                          <th>Date</th>
                          <th>Reason</th>
                        </tr>
                      </thead>
                      <tbody>
                        <tr v-for="(remark, i) in remarks" :key="remark.id">
                          <td>{{ i + 1 }}</td>
                          <td>Director</td>
                          <td>
                            {{ new Date(remark.created_at).toLocaleDateString("en-GB") }}
                          </td>
                          <td>{{ remark.remark }}</td>
                        </tr>
                      </tbody>
                    </table>
                  </div>
                </div>

                <!-- Issuing Items -->

                <!-- Proforma -->
                <div class="col-xl-6 col-lg-12 col-sm-12 layout-spacing" v-if="proforma">
                  <div class="panel p-3 position-relative">
                    <a :href="proforma" target="_blank" class="stretched-link"></a>
                    <h4 class="text-center">Proforma Invoice</h4>
                    <embed
                      :src="proforma"
                      type="application/pdf"
                      width="100%"
                      height="600px"
                    />
                  </div>
                </div>
              </div>
            </form>
          </div>

          <!-- Footer -->
          <div class="modal-footer">
            <button
              type="button"
              class="btn btn-secondary"
              data-bs-dismiss="modal"
              @click="clearForm"
            >
              Close
            </button>
          </div>
        </div>
      </div>
    </div>
    <!-- requisition items ends -->

    <!-- edit requisition modal starts -->
    <div
      class="modal fade mymodal"
      id="edit-requisition-modal"
      data-bs-backdrop="false"
      data-bs-keyboard="false"
      tabindex="-1"
      aria-labelledby="editRequisitionModalLabel"
      aria-hidden="true"
    >
      <div class="modal-dialog modal-xl">
        <div class="modal-content">
          <div class="modal-header">
            <h1 class="modal-title fs-5" id="editRequisitionModalLabel">
              Edit Requisition
            </h1>
            <button
              type="button"
              class="btn-close"
              data-bs-dismiss="modal"
              aria-label="Close"
              @click="closeEditModal()"
            ></button>
          </div>
          <form @submit.prevent="updateRequisition()">
            <div class="modal-body">
              <div class="row">
                <div class="col-md-4">
                  <label for="description">Status</label>
                  <multiselect
                    v-model="stat"
                    :options="statuses"
                    placeholder="Select Status"
                    label="name"
                    :searchable="true"
                    multple="false"
                    :required="true"
                    :allow-empty="false"
                  ></multiselect>
                </div>
                <div class="col-md-4">
                  <div>
                    <label class="form-label small">Select Cost Center</label>
                    <multiselect
                      v-model="proj"
                      :options="projects"
