const isAllowedTime = () => {
  if (!activity.value || !activity.value.start_time || !activity.value.end_time)
    return false;

  const now = new Date();
  const current = now.getHours() * 60 + now.getMinutes();

  const [startH, startM] = activity.value.start_time.split(":").map(Number);
  const [endH, endM] = activity.value.end_time.split(":").map(Number);

  const start = startH * 60 + startM;
  const end = endH * 60 + endM;

  if (activity.value.infinity_open == 1) return true;

  if (start === end) return current === start;

  if (start < end) {
    return current >= start && current <= end;
  } else {
    return current >= start || current <= end;
  }
};

