const filteredRequisitions = computed(() => {
  let filtered = requisitions.value;

  if (user_permissions.includes("is_md")) {
    if (showTrash.value) {
      filtered = filtered.filter((r) =>
        ["Rejected", "On Hold", "Remarked"].includes(r.status?.key)
      );
    } else {
      filtered = filtered.filter((r) =>
        ["Unapproved", "approved"].includes(r.status?.key)
      );
    }
  }

  if (filter.value) {
    const keyword = filter.value.toLowerCase();
    filtered = filtered.filter(
      (r) =>
        (r.requester && r.requester.toLowerCase().includes(keyword)) ||
        (r.project && r.project.toLowerCase().includes(keyword)) ||
        (r.description && r.description.toLowerCase().includes(keyword)) ||
        (r.remark && r.remark.toLowerCase().includes(keyword)) ||
        (r.items &&
          r.items.some(
            (item) =>
              (item.description && item.description.toLowerCase().includes(keyword)) ||
              (item.receiver && item.receiver.toLowerCase().includes(keyword)) ||
              (item.remark && item.remark.toLowerCase().includes(keyword))
          ))
    );
  }

  return filtered;
});

