const pushItem = () => {
  // Handle multiple store items for store requisitions (incidence.id === 6)
  if (incidence?.value?.id === 6 && selectedStoreItems.value.length > 0) {
    // Validate all selected items have quantities
    let hasError = false;
    for (const storeItem of selectedStoreItems.value) {
      if (!storeItem.qty || storeItem.qty <= 0) {
        showError(`Please enter quantity for ${storeItem.name}`);
        hasError = true;
        return;
      }
      if (!storeItem.unit || !storeItem.unit.short_name) {
        showError(`Please select unit for ${storeItem.name}`);
        hasError = true;
        return;
      }
    }

    if (hasError) return;

    // Process each selected store item
    selectedStoreItems.value.forEach((storeItem) => {
      // Display payload (formatted for table display)
      const displayPayload = {
        Sno: i.value,
        item_id: storeItem.id,
        quantity: storeItem.qty,
        units: storeItem.unit?.short_name || storeItem.unit,
        rate: Number(0).toLocaleString() + "/=",
        item: storeItem.name,
        description: storeItem.descr || storeItem.description || "",
        total: Number(0 * storeItem.qty).toLocaleString() + "/=",
        receiver: beneficiary.value || vendor.value?.name || "No Receiver",
      };

      // Backend payload (actual data for API)
      const backendPayload = {
        Sno: i.value,
        item_id: storeItem.id,
        quantity: storeItem.qty,
        category_id: null,
        category_ref_id: null,
        rate: Number(0),
        remark: storeItem.name,
        description: storeItem.descr || storeItem.description || "",
        units: storeItem.unit?.short_name || storeItem.unit,
        asset_id: asset.value.id || null,
        vendor_id: beneficiary.value ? null : vendor.value?.id || null,
        beneficiary: beneficiary.value || null,
        store_item_id: storeItem.id,
      };

      formRequisitionItems.value.push(displayPayload);
      formRequisitionItems2.value.push(backendPayload);
      i.value++;
    });

    // Clear selected store items after adding
    selectedStoreItems.value = [];
    return;
  }

  // Handle single item for other requisition types
  if (!quantity.value || quantity.value <= 0) {
    showError("Please fill quantity field");
    return;
  }

  if (!units.value || !units.value.short_name) {
    showError("Please select unit");
    return;
  }

  // Determine the item ID based on requisition type and incidence
  let selectedItemId = item_id.value;
  let selectedItemName = "";

  if (incidence?.value?.id === 6 && item.value) {
    selectedItemId = item.value.id;
    selectedItemName = item.value.name;
  } else if (item.value && typeof item.value === "object") {
    selectedItemId = item.value.id;
    selectedItemName = item.value.name;
  } else if (binCard.value && typeof binCard.value === "object") {
    selectedItemId = binCard.value.id;
    selectedItemName = binCard.value.name;
  } else if (item.value && typeof item.value === "string") {
    selectedItemId = item_id.value;
    selectedItemName = item.value;
  }

  // Validate vendor/beneficiary for non-store requisitions
  if (!vendor.value?.id && !beneficiary.value && incidence.value.id !== 6) {
    showError("Vendor or Beneficiary is required");
    return;
  }

  // Display payload (formatted for table display)
  const displayPayload = {
    Sno: i.value,
    item_id: selectedItemId,
    quantity: quantity.value,
    units: units.value?.short_name || units.value,
    rate: Number(rate.value).toLocaleString() + "/=",
    item: ["spares", "labour", "construction materials"].includes(requisition_type.value)
      ? item.value?.name || item.value
      : item.value || binCard.value?.name || "",
    description: asset?.value
      ? description.value + " For " + asset.value.name
      : description.value,
    total: Number(rate.value * quantity.value).toLocaleString() + "/=",
    receiver: beneficiary.value || vendor.value?.name || "No Receiver",
  };

  // Backend payload (actual data for API)
  const backendPayload = {
    Sno: i.value,
    item_id: selectedItemId,
    quantity: quantity.value,
    category_id: project.value?.id === "all" ? 4 : null,
    category_ref_id: binCard.value?.id || null,
    rate: Number(rate.value),
    remark: ["spares", "labour", "construction materials"].includes(
      requisition_type.value
    )
      ? item.value?.name || item.value
      : item.value || binCard.value?.name || "",
    description: asset?.value
      ? description.value + " For " + asset.value.name
      : description.value,
    units: units.value?.short_name || units.value,
    asset_id: asset.value?.id || null,
    vendor_id: beneficiary.value ? null : vendor.value?.id || null,
    beneficiary: beneficiary.value || null,
  };

  // Add to both arrays
  i.value = i.value + 1;
  formRequisitionItems.value.push(displayPayload);
  formRequisitionItems2.value.push(backendPayload);

  // Clear the item form
  clearItemForm();
};

