const isWaiting = ref(false);
const showConfirmation = inject("showConfirmation");
const pleaseWait = inject("waitIndicator");

const DeleteRequisition = async (requisition) => {
  try {
    isWaiting.value = true;
    const res = await showConfirmation(
      "Delete Requisition",
      `Are you sure you want to delete Requisition No. ${requisition.ref_no} with cost ${requisition.cost}?`,
      `update-requisition/${requisition.id}?deleted=1`,
      "put"
    );

    if (res?.refresh) {
      getRequisitions();
    }
  } catch (error) {
    console.error(error);
    showError(error.message);
  } finally {
    isWaiting.value = false;
  }
};

